#pragma once
// The presets' static curves and linear models (doc/N28, M2), exported from the M0 circuits (verify/curve_export.py)
// and built into the engine (color/src/preset_curves.inc, generated by verify/curve_to_cpp.py).
//
// The curve f is on the digital scale u = d x (u = 1: the input at which -18 dBFS RMS pink noise gives the preset's
// reference power at drive 100 %), with f(0) = 0 and f'(0) = 1: the small-signal gain is the linear model's. It is a
// table on a uniform grid over [-u_max, u_max] read with a monotone cubic (Hermite, the slopes the harmonic mean of
// the neighbouring steps: Fritsch-Butland; a Catmull-Rom cubic overshoots where the curve turns flat); beyond the table
// it holds its last value (defined, never extrapolated). Its ranges, in u:
//   u_rated     up to the preset's rated power: checked against the circuit (H2 - H5 within 0.2 dB for set-300b)
//   u_no_grid   up to where the output tube's grid starts to conduct (the transition, still checked)
//   u_data      the largest drive the circuit was run at; beyond u_no_grid the curve is defined, not calibrated: a
//               static curve cannot follow the bias shift grid current makes (N28)

#include <string_view>
#include <vector>

#include "daphne/color/linear.h"

namespace daphne::color {

struct PresetCurve {
    const char* id;          // the settings' preset name ("set-300b")
    const double* f;
    int n;
    double u_max;
    LinearModel linear;
    double u_rated, u_no_grid, u_data;
    // the strength's H2 for a 1 kHz sine at -18 dBFS RMS (h2-pure: the panel shows it), h2_n pairs of drive, percent
    const double* h2 = nullptr;
    int h2_n = 0;

    double operator()(double u) const {
        const double p = (u + u_max) * (n - 1) / (2.0 * u_max);
        if (p <= 0.0) return f[0];
        if (p >= n - 1) return f[n - 1];
        const int i = static_cast<int>(p);
        const double t = p - i;
        const double y0 = f[i > 0 ? i - 1 : 0], y1 = f[i], y2 = f[i + 1], y3 = f[i + 2 < n ? i + 2 : n - 1];
        const double d0 = y1 - y0, d1 = y2 - y1, d2 = y3 - y2;
        auto slope = [](double a, double b) { return a * b > 0.0 ? 2.0 * a * b / (a + b) : 0.0; };
        const double m1 = i > 0 ? slope(d0, d1) : d1, m2 = i + 2 < n ? slope(d1, d2) : d1;
        // Hermite on [y1, y2] with the slopes m1, m2 (per grid step)
        const double t2 = t * t, t3 = t2 * t;
        return (2 * t3 - 3 * t2 + 1) * y1 + (t3 - 2 * t2 + t) * m1 + (-2 * t3 + 3 * t2) * y2 + (t3 - t2) * m2;
    }
};

// The preset's curve, or nullptr when it has not been exported yet (the preset cannot run in this build).
const PresetCurve* preset_curve(std::string_view id);

// The virtual loudspeaker load (doc/N28, verify/load_filters.py): for a preset (its feedback step for pp-el34-ul,
// -1 otherwise) and a load, the sections that change the response from the 8 ohm resistor's to the loudspeaker's
// (|Z / (Z + Zout)| / |8 / (8 + Zout)|, Zout the preset's output impedance) and their makeup gain (the median loudness
// change on the six test tracks). The 8 ohm resistor has none. M3's bias will change Zout: the data is keyed by what
// Zout depends on.
struct PresetLoad {
    const char* preset;
    int feedback_db;      // -1: not a push-pull preset
    const char* load;     // the settings' name ("bookshelf-vented")
    std::vector<Section> sections;
    double makeup_db;
};
const PresetLoad* preset_load(std::string_view preset, int feedback_db, std::string_view load);

}  // namespace daphne::color
